242	    @Override
243	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
244	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
245	        if (currentOwner != null) {
246	            Pet currentPet = this.clinicService.findPetById(petId);
247	            if (currentPet != null) {
248	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
249	                currentPet.setName(petFieldsDto.getName());
250	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
251	                this.clinicService.savePet(currentPet);
252	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
253	            }
254	        }
255	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	    }
257	
258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Override
260	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
261	        HttpHeaders headers = new HttpHeaders();
262	        Visit visit = visitMapper.toVisit(visitFieldsDto);
263	        Pet pet = new Pet();
264	        pet.setId(petId);
265	        visit.setPet(pet);
266	        this.clinicService.saveVisit(visit);
267	        VisitDto visitDto = visitMapper.toVisitDto(visit);
268	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
269	            .buildAndExpand(visit.getId()).toUri());
270	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
271	    }
272	
273	
274	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
275	    @Override
276	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
277	        Owner owner = this.clinicService.findOwnerById(ownerId);
278	        if (owner != null) {
279	            Pet pet = owner.getPet(petId);
280	            if (pet != null) {
281	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
282	            }
283	        }
284	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
285	    }
286	
287	    /**
288	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
289	     * offending field is collected so the caller learns exactly which values must be supplied.
290	     *
291	     * @param ownerFieldsDto the submitted owner payload
292	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
293	     *         telephone is missing or blank
294	     */
295	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
296	        List<String> missingFields = new ArrayList<>();
297	        if (isBlank(ownerFieldsDto.getFirstName())) {
298	            missingFields.add("firstName");
299	        }
300	        if (isBlank(ownerFieldsDto.getLastName())) {
301	            missingFields.add("lastName");
302	        }
303	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
304	            missingFields.add("address");
305	        }
306	        if (isBlank(ownerFieldsDto.getCity())) {
307	            missingFields.add("city");
308	        }
309	        if (isBlank(ownerFieldsDto.getTelephone())) {
310	            missingFields.add("telephone");
311	        }
312	        if (!missingFields.isEmpty()) {
313	            throw new MissingOwnerFieldsException(missingFields);
314	        }
315	    }
316	
317	    private boolean isBlank(String value) {
318	        return value == null || value.isBlank();
319	    }
320	
321	    /**
322	     * Rejects an owner create whose supplied {@code registrationDate} is later than the server's
323	     * current date. A registration date may not lie in the future; a value equal to today or in the
324	     * past is accepted, and an absent date is left to default to the server date.
325	     *
326	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
327	     * @throws InvalidOwnerFieldsException if the supplied date is after the server's current date
328	     */
329	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
330	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
331	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
332	        }
333	    }
334	
335	    /**
336	     * Counts the existing owners who, before this create, already share the given first and last name.
337	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
338	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
339	     * case or spacing still count as the same name.
340	     *
341	     * @param firstName the first name of the owner being created
342	     * @param lastName the last name of the owner being created
343	     * @return the number of existing owners sharing both names (zero when none)
344	     */
345	    private int countNamesakes(String firstName, String lastName) {
346	        String first = normalizeHouseholdField(firstName);
347	        String last = normalizeHouseholdField(lastName);
348	        return (int) this.clinicService.findAllOwners().stream()
349	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
350	                && normalizeHouseholdField(existing.getLastName()).equals(last))
351	            .count();
352	    }
353	
354	    /**
355	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
356	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
357	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
358	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
359	     * more owners the create is rejected as a conflict.
360	     *
361	     * @param city the city of the owner being created
362	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
363	     */
364	    /**
365	     * Rejects an owner create once the maximum number of owners have already been registered on the
366	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
367	     * which is always a business day (a weekend effective date is rolled forward to the following
368	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
369	     * business day the create is rejected as too many requests. Because a weekend effective date is
370	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
371	     *
372	     * @param businessDay the adjusted business day the owner being created would be registered on
373	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
374	     */
375	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
376	        long ownersOnDay = this.clinicService.findAllOwners().stream()
377	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
378	            .count();
379	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
380	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
381	        }
382	    }
383	
384	    /**
385	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
386	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
387	     * was supplied on the request or defaulted to the server's current date.
388	     *
389	     * @param date the effective registration date (supplied or defaulted)
390	     * @return the same date when it is a weekday, otherwise the following Monday
391	     */
392	    /**
393	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
394	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
395	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
396	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
397	     *
398	     * @return {@code true} when more than the threshold number of owners are already registered on
399	     *         today's business day, otherwise {@code false}
400	     */
401	    private boolean isBulkSignupWarningActive() {
402	        LocalDate today = toBusinessDay(LocalDate.now());
403	        long ownersToday = this.clinicService.findAllOwners().stream()
404	            .filter(existing -> today.equals(existing.getRegistrationDate()))
405	            .count();
406	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
407	    }
408	
409	    private LocalDate toBusinessDay(LocalDate date) {
410	        return switch (date.getDayOfWeek()) {
411	            case SATURDAY -> date.plusDays(2);
412	            case SUNDAY -> date.plusDays(1);
413	            default -> date;
414	        };
415	    }
416	
417	    private void rejectCityAtCapacity(String city) {
418	        String normalizedCity = normalizeHouseholdField(city);
419	        long ownersInCity = this.clinicService.findAllOwners().stream()
420	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
421	            .count();
422	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
423	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
424	        }
425	    }
426	
427	    /**
428	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
429	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
430	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
431	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). The code carries no
432	     * sequence number; two owners resolve to the same code only when they share a region and produce the
433	     * same telephone-and-last-name hash.
434	     *
435	     * @param postcode the owner's postcode, used first to derive the region
436	     * @param city the owner's city, used to derive the region when the postcode maps to none
437	     * @param normalizedTelephone the owner's normalized (E.164) telephone
438	     * @param lastName the owner's last name
439	     * @return the formatted customer code
440	     */
441	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
442	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
443	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
444	        return region + "-" + hash8;
445	    }
446	
447	    /**
448	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
449	     * customerCode is the owner's customer code and YY is the last two digits of the
450	     * registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
451	     *
452	     * @param customerCode the owner's customer code
453	     * @param registrationDate the owner's registration date
454	     * @return the formatted membership number
455	     */
456	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
457	        String yy = String.format("%02d", registrationDate.getYear() % 100);
458	        return customerCode + "-M" + yy;
459	    }
460	
461	    /**
462	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
463	     * country calling code. Australia ('+61') uses 9 national digits and the North American
464	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
465	     * E.164 length (8 to 15 digits overall).
466	     */
467	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
468	        java.util.Map.of("61", 9, "1", 10);
469	
470	    /**
471	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
472	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
473	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
474	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
475	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
476	     * E.164 string is what gets stored and returned.
477	     *
478	     * @param telephone the raw telephone value from the request
479	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
480	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
481	     *         national number has the wrong length for its country code
482	     */
483	    private String normalizeTelephone(String telephone) {
484	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
485	        String e164;
486	        if (cleaned.startsWith("+")) {
487	            e164 = cleaned;
488	        } else {
489	            String national = cleaned;
490	            if (national.startsWith("0")) {
491	                national = national.substring(1);
492	            }
493	            e164 = "+61" + national;
494	        }
495	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
496	            throw new InvalidOwnerFieldsException(List.of("telephone"));
497	        }
498	        validateNationalNumberLength(e164);
499	        return e164;
500	    }
501	
502	    /**
503	     * Rejects an E.164 telephone whose national number does not have the exact length its country
504	     * calling code requires. The digits after the leading '+' are split into the longest matching
505	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
506	     * code is known and the national number's length differs from the required count the telephone is
507	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
508	     *
509	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
510	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
511	     */
512	    private void validateNationalNumberLength(String e164) {
513	        String digits = e164.substring(1);
514	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
515	            String countryCode = digits.substring(0, codeLength);
516	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
517	            if (requiredNationalLength != null) {
518	                int nationalLength = digits.length() - codeLength;
519	                if (nationalLength != requiredNationalLength) {
520	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
521	                }
522	                return;
523	            }
524	        }
525	    }
526	
527	    /**
528	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
529	     * left unset. When a value is present it must be a syntactically valid address; the normalized
530	     * form stored and returned is the value lower-cased.
531	     *
532	     * @param email the raw email value from the request, or {@code null} when none was supplied
533	     * @return the lower-cased email, or {@code null} when no email was supplied
534	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
535	     */
536	    private String normalizeEmail(String email) {
537	        if (email == null || email.isBlank()) {
538	            return null;
539	        }
540	        if (!EMAIL_PATTERN.matcher(email).matches()) {
541	            throw new InvalidOwnerFieldsException(List.of("email"));
542	        }
543	        return email.toLowerCase(Locale.ROOT);
544	    }
545	
546	    /**
547	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
548	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
549	     * When present it must be exactly four digits and, when the owner's city maps to a known region
550	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
551	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
552	     * region accepts any four-digit postcode.
553	     *
554	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
555	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
556	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
557	     *         for the city's region
558	     */
559	    private void validatePostcode(String city, String postcode) {
560	        if (postcode == null || postcode.isBlank()) {
561	            return;
562	        }
563	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
564	            throw new InvalidOwnerFieldsException(List.of("postcode"));
565	        }
566	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
567	        if (range == null) {
568	            return;
569	        }
570	        int value = Integer.parseInt(postcode);
571	        if (value < range[0] || value > range[1]) {
572	            throw new InvalidOwnerFieldsException(List.of("postcode"));
573	        }
574	    }
575	
576	    /**
577	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
578	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
579	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
580	     * normalized form is what gets stored, returned and used for every address comparison (the
581	     * required-field check, household duplicate detection and the shared household id).
582	     *
583	     * @param address the raw address value from the request, or {@code null}
584	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
585	     */
586	    private String normalizeAddress(String address) {
587	        if (address == null) {
588	            return "";
589	        }
590	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
591	        if (collapsed.isEmpty()) {
592	            return "";
593	        }
594	        String[] tokens = collapsed.split(" ");
595	        for (int i = 0; i < tokens.length; i++) {
596	            switch (tokens[i]) {
597	                case "ST" -> tokens[i] = "STREET";
598	                case "RD" -> tokens[i] = "ROAD";
599	                case "AVE" -> tokens[i] = "AVENUE";
600	                default -> { }
601	            }
602	        }
603	        return String.join(" ", tokens);
604	    }
605	
606	    /**
607	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
608	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
609	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
610	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
611	     * so two members of one household with different telephones have different keys and are both
612	     * allowed; only an owner whose entire key is identical is a duplicate.
613	     *
614	     * @param owner the owner being created, with its telephone, email and householdId already resolved
615	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
616	     */
617	    private void rejectDuplicateIdentity(Owner owner) {
618	        String identityKey = owner.getIdentityKey();
619	        boolean inUse = this.clinicService.findAllOwners().stream()
620	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
621	        if (inUse) {
622	            throw new DuplicateOwnerIdentityException(identityKey);
623	        }
624	    }
625	
626	    /**
627	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
628	     * last name and a normalized address: last names are compared case-insensitively after whitespace
629	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
630	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
631	     * abbreviation still count as the same household.
632	     * <p>
633	     * When the owner's last name and address already belong to at least one other owner and
634	     * {@code sharesHousehold} is true, every member of the household - the existing owners and this
635	     * joiner - is assigned the same stable {@code householdId}, which is returned on read and forms
636	     * the third component of the {@code identityKey}. When {@code sharesHousehold} is not true, or no
637	     * other owner shares the last name and address, no identifier is assigned. Household membership no
638	     * longer rejects a create on its own; duplicates are detected solely through the identity key.
639	     *
640	     * @param owner the owner being created
641	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
642	     */
643	    /**
644	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
645	     * household member count} for the response.
646	     *
647	     * @param owner the owner to map
648	     * @return the mapped owner DTO
649	     */
650	    private OwnerDto toOwnerDto(Owner owner) {
651	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
652	        return ownerMapper.toOwnerDto(owner);
653	    }
654	
655	    /**
656	     * Counts the members of the given owner's household - the owners that share this owner's
657	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
658	     * is {@code null}) is its own sole member, so the count is one.
659	     *
660	     * @param owner the owner whose household is being sized
661	     * @return the number of owners sharing this owner's household (one when it has no household)
662	     */
663	    private int countHouseholdMembers(Owner owner) {
664	        String householdId = owner.getHouseholdId();
665	        if (householdId == null) {
666	            return 1;
667	        }
668	        return (int) this.clinicService.findAllOwners().stream()
669	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
670	            .count();
671	    }
672	
673	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
674	        String lastName = normalizeHouseholdField(owner.getLastName());
675	        String address = normalizeAddress(owner.getAddress());
676	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
677	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
678	                && normalizeAddress(existing.getAddress()).equals(address))
679	            .toList();
680	        if (housemates.isEmpty()) {
681	            return;
682	        }
683	        if (!Boolean.TRUE.equals(sharesHousehold)) {
684	            return;
685	        }
686	        String householdId = generateHouseholdId(lastName, address);
687	        owner.setHouseholdId(householdId);
688	        for (Owner housemate : housemates) {
689	            if (!householdId.equals(housemate.getHouseholdId())) {
690	                housemate.setHouseholdId(householdId);
691	                this.clinicService.saveOwner(housemate);
692	            }
693	        }
694	    }
695	
696	    /**
697	     * Builds the stable identifier shared by the members of one household. It is derived purely from
698	     * the normalized last name and address, so every owner of a given household deterministically
699	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
700	     * two normalized fields joined by a single space.
701	     *
702	     * @param normalizedLastName the household's last name, already normalized for comparison
703	     * @param normalizedAddress the household's address, already normalized for comparison
704	     * @return the shared household identifier
705	     */
706	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
707	        String key = normalizedLastName + '�' + normalizedAddress;
708	        try {
709	            byte[] digest = MessageDigest.getInstance("SHA-256")
710	                .digest(key.getBytes(StandardCharsets.UTF_8));
711	            StringBuilder hex = new StringBuilder();
712	            for (byte b : digest) {
713	                hex.append(String.format("%02X", b));
714	                if (hex.length() >= 12) {
715	                    break;
716	                }
717	            }
718	            return hex.substring(0, 12);
719	        } catch (NoSuchAlgorithmException e) {
720	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
721	        }
722	    }
723	
724	    /**
725	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
726	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
727	     * the owner's normalized telephone and last name.
728	     *
729	     * @param input the string to digest
730	     * @param length the number of leading upper-case hex characters to return
731	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
732	     */
733	    private String sha256UpperHex(String input, int length) {
734	        try {
735	            byte[] digest = MessageDigest.getInstance("SHA-256")
736	                .digest(input.getBytes(StandardCharsets.UTF_8));
737	            StringBuilder hex = new StringBuilder();
738	            for (byte b : digest) {
739	                hex.append(String.format("%02X", b));
740	                if (hex.length() >= length) {
741	                    break;
742	                }
743	            }
744	            return hex.substring(0, length);
745	        } catch (NoSuchAlgorithmException e) {
746	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
747	        }
748	    }
749	
750	    /**
751	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
752	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
753	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
754	     * expands common abbreviations.
755	     *
756	     * @param value the raw last name, or {@code null}
757	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
758	     */
759	    private String normalizeHouseholdField(String value) {
760	        if (value == null) {
761	            return "";
762	        }
763	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
764	    }
765	}
